import Ajv, {type ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validator?: ValidateFunction;
}

function escapePointerSegment(segment: string): string {
  return segment.replace(/~/g, '~0').replace(/\//g, '~1');
}

function normalizeMissingProperty(property: string): string {
  return property.replace(/^\[['"](.+)['"]\]$/, '$1');
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly dynamicValidators = new WeakMap<object, ValidateFunction>();
  private readonly ajv = new Ajv({strict: false, validateFormats: false} as ConstructorParameters<typeof Ajv>[0]);

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  private compileValidator(name: string, schema: Record<string, unknown>): ValidateFunction {
    try {
      return this.ajv.compile(schema);
    } catch (error) {
      throw new Error(`Invalid inputSchema for tool ${name}: ${String(error)}`, {cause: error});
    }
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    let validator: ValidateFunction | undefined;
    if (typeof definition !== 'function') {
      validator = this.compileValidator(resolved.name, resolved.inputSchema);
    }
    this.tools.set(resolved.name, {definitionSource: definition, execute, validator});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  private rejectInput(name: string, validator: ValidateFunction): ToolResponse {
    const error = validator.errors?.[0];
    const instancePath =
      error && 'instancePath' in error
        ? String(error.instancePath)
        : error && 'dataPath' in error
          ? String(error.dataPath).replace(
              /\.([^.[\]]+)|\[['"]?([^'"\]]+)['"]?\]/g,
              (_match, dotted: string | undefined, bracketed: string | undefined) =>
                `/${escapePointerSegment(dotted ?? bracketed ?? '')}`
            )
          : '';
    const missingProperty =
      error && 'missingProperty' in error.params ? normalizeMissingProperty(String(error.params.missingProperty)) : '';
    const path =
      error?.keyword === 'required' ? `${instancePath}/${escapePointerSegment(missingProperty)}` : instancePath || '/';
    let constraint = error?.keyword ? `must satisfy ${error.keyword} constraint` : 'does not match the schema';
    if (error?.keyword === 'required') constraint = `must have required property '${missingProperty}'`;
    if (error?.keyword === 'type' && 'type' in error.params) constraint = `must be ${String(error.params.type)}`;
    if (error?.keyword === 'enum') constraint = 'must match enum';
    log.warn('tool', 'input rejected', {name, path, constraint});
    return {result: `Invalid tool input at ${path}: ${constraint}`};
  }

  /** Validate input per specs/hal-engine-tool-input-validation/spec.md before executing a registered tool. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    let validator = tool.validator;
    if (!validator) {
      const schema = this.resolveDefinition(tool.definitionSource).inputSchema;
      validator = this.dynamicValidators.get(schema) ?? this.compileValidator(name, schema);
      this.dynamicValidators.set(schema, validator);
    }
    if (!validator(input)) return this.rejectInput(name, validator);
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}

import {jest} from '@jest/globals';
import Ajv, {type ValidateFunction} from 'ajv';
import {setLogger} from '../../shared/logger.js';
import {ToolRegistry} from './registry.js';

function mockValidatorError(error: NonNullable<ValidateFunction['errors']>[number]) {
  const validator = (() => false) as ValidateFunction;
  validator.errors = [error];
  return jest.spyOn(Ajv.prototype, 'compile').mockReturnValue(validator);
}

function registerWeatherTool(): ToolRegistry {
  const registry = new ToolRegistry();
  registry.register(
    {
      name: 'weather',
      description: 'Get weather',
      inputSchema: {type: 'object', properties: {address: {type: 'object', properties: {city: {type: 'string'}}}}},
    },
    async () => 'sunny'
  );
  return registry;
}

function registerLookupTool(registry: ToolRegistry, execute: () => Promise<string>): void {
  registry.register(
    {
      name: 'lookup',
      description: 'Look up a profile',
      inputSchema: {type: 'object', properties: {profile: {type: 'object', required: ['home/address']}}},
    },
    execute
  );
}

describe('ToolRegistry schema registration', () => {
  // specs/hal-engine-tool-input-validation/spec.md#5
  it('rejects an invalid static input schema while registering the named tool', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'weather',
          description: 'Get weather',
          inputSchema: {type: 'object', properties: {location: {type: 'invalid-type'}}},
        },
        async () => 'sunny'
      )
    ).toThrow(/weather/);
  });
});

describe('ToolRegistry dynamic schema validation', () => {
  // specs/hal-engine-tool-input-validation/spec.md#7
  it('compiles each dynamic schema object once and validates against the current one', async () => {
    const locationSchema = {type: 'object', properties: {location: {type: 'string'}}, required: ['location']};
    const citySchema = {type: 'object', properties: {city: {type: 'string'}}, required: ['city']};
    let currentSchema: Record<string, unknown> = locationSchema;
    const execute = jest.fn(async () => 'sunny');
    const compile = jest.spyOn(Ajv.prototype, 'compile');
    const registry = new ToolRegistry();
    registry.register(() => ({name: 'weather', description: 'Get weather', inputSchema: currentSchema}), execute);

    try {
      await registry.execute('weather', {location: 'Paris'});
      await registry.execute('weather', {location: 'Berlin'});
      currentSchema = citySchema;
      const rejected = await registry.execute('weather', {location: 'Paris'});

      expect(/city.*required|required.*city/i.test(rejected.result)).toBe(true);
      expect(compile).toHaveBeenCalledTimes(2);
      expect(execute).toHaveBeenCalledTimes(2);
    } finally {
      compile.mockRestore();
    }
  });
});

describe('ToolRegistry input rejection', () => {
  // specs/hal-engine-tool-input-validation/spec.md#2
  it('logs the expected type and field path for a rejected tool input', async () => {
    const warn = jest.fn();
    setLogger({debug: () => undefined, info: () => undefined, warn, error: () => undefined});
    try {
      const registry = new ToolRegistry();
      registry.register(
        {
          name: 'weather',
          description: 'Get weather',
          inputSchema: {type: 'object', properties: {location: {type: 'string'}}},
        },
        async () => 'sunny'
      );

      await registry.execute('weather', {location: 123456789});

      expect(warn).toHaveBeenCalledWith(
        'tool',
        'input rejected',
        expect.objectContaining({path: '/location', constraint: 'must be string'})
      );
      expect(JSON.stringify(warn.mock.calls)).not.toContain('123456789');
    } finally {
      setLogger();
    }
  });

  // specs/hal-engine-tool-input-validation/spec.md#3
  it('names the enum constraint without exposing the rejected value', async () => {
    const registry = new ToolRegistry();
    let executions = 0;
    registry.register(
      {
        name: 'lookup',
        description: 'Look up a profile',
        inputSchema: {type: 'object', properties: {profile: {type: 'object', properties: {region: {enum: ['eu']}}}}},
      },
      async () => {
        executions += 1;
        return 'found';
      }
    );

    const response = await registry.execute('lookup', {profile: {region: 'private-region'}});

    expect({
      path: response.result.includes('/profile/region'),
      constraint: response.result.includes('enum'),
      leaksValue: response.result.includes('private-region'),
      executions,
    }).toEqual({path: true, constraint: true, leaksValue: false, executions: 0});
  });

  // specs/hal-engine-tool-input-validation/spec.md#1
  it('escapes a required field name in the rejection path without invoking the executor', async () => {
    const registry = new ToolRegistry();
    const execute = jest.fn(async () => 'found');
    registerLookupTool(registry, execute);

    const response = await registry.execute('lookup', {profile: {}});

    expect(response.result).toBe(
      "Invalid tool input at /profile/home~1address: must have required property 'home/address'"
    );
    expect(execute).toHaveBeenCalledTimes(0);
  });

  // specs/hal-engine-tool-input-validation/spec.md#1
  it('normalizes a legacy required-property error with a slash', async () => {
    const compile = mockValidatorError({
      keyword: 'required',
      dataPath: '.profile',
      schemaPath: '#/properties/profile/required',
      params: {missingProperty: "['home/address']"},
      message: "should have required property '['home/address']'",
    });
    const registry = new ToolRegistry();
    const execute = jest.fn(async () => 'found');
    try {
      registerLookupTool(registry, execute);

      const response = await registry.execute('lookup', {profile: {}});

      expect(response.result).toBe(
        "Invalid tool input at /profile/home~1address: must have required property 'home/address'"
      );
      expect(execute).toHaveBeenCalledTimes(0);
    } finally {
      compile.mockRestore();
    }
  });
});

describe('ToolRegistry nested input rejection', () => {
  // specs/hal-engine-tool-input-validation/spec.md#2
  it('does not echo a validator message containing the rejected property value', async () => {
    const compile = mockValidatorError({
      keyword: 'type',
      dataPath: '.address.city',
      schemaPath: '#/properties/address/properties/city/type',
      params: {type: 'string'},
      message: 'value 123456789 should be string',
    });
    try {
      const registry = registerWeatherTool();
      const response = await registry.execute('weather', {address: {city: 123456789}});

      expect(response.result).toBe('Invalid tool input at /address/city: must be string');
    } finally {
      compile.mockRestore();
    }
  });

  // specs/hal-engine-tool-input-validation/spec.md#2
  it('names a nested wrong-typed field from a dataPath error without echoing its value', async () => {
    const compile = mockValidatorError({
      keyword: 'type',
      dataPath: '.address.city',
      schemaPath: '#/properties/address/properties/city/type',
      params: {type: 'string'},
      message: 'should be string',
    });
    try {
      const registry = registerWeatherTool();
      const response = await registry.execute('weather', {address: {city: 123456789}});

      expect({
        path: response.result.includes('/address/city'),
        type: response.result.includes('string'),
        leaksValue: response.result.includes('123456789'),
      }).toEqual({path: true, type: true, leaksValue: false});
    } finally {
      compile.mockRestore();
    }
  });
});

